PREFIX chorus: <https://jeffbridwell.com/chorus#>
SELECT DISTINCT ?s WHERE {
  GRAPH ?g { ?s a chorus:Skill ; chorus:runsAs ?r }
  BIND(STRBEFORE(STRAFTER(STR(?s), "#skill-"), "-") AS ?prod)
  FILTER NOT EXISTS { GRAPH ?h { ?p a chorus:Product } FILTER(STRAFTER(STR(?p), "#") = ?prod) }
}
